    }
    &.selected {
      background-color: #ffffff39;
    }
    .avatar {
      img {
        height: 60px;
        width: 60px;
        border-radius: 100%;
        object-fit: cover;
      }
    }
    .chat_info {
      width: 100%;
      display: flex;
      height: 60px;
      flex-direction: column;
      justify-content: center;
      min-width: 0;
      row-gap: 5px;
      padding-right: 15px;
      .top {
        display: flex;
        align-items: center;
        line-height: 2.5;
        color: hsl(280 100% 94%);
        .username {
          flex: 1;
          overflow: hidden;
          white-space: nowrap;
          text-overflow: ellipsis;
          font: 400 1rem var(--MontserratFont);
        }
        .time {
          font: 400 0.7rem system-ui;
          padding-left: 8px;
        }
      }
      .bottom {
        p {
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
